return async function run(task) {
  if (active >= concurrency) {
    await new Promise((resolve) => waiting.push(resolve));
  } else {
    active += 1;
  }
  const result = await task();
  active -= 1;
  waiting.shift()?.();   // wake the next waiting task
  return result;
};

